// The xicap C++ reader, compiled to WebAssembly with Emscripten and Embind.
//
//   import { Reader, StreamReader } from "@xicap/wasm";
//   const r = await Reader.open(bytes);
//   for (const pkt of r) { ... }
//   r.verify().signedToEnd;
//   r.close();
//
//   const s = await StreamReader.create();
//   for await (const chunk of download) for (const pkt of s.push(chunk)) { ... }
//   s.close();
//
// `bytes` is an ArrayBuffer or any typed array. Reader copies all of it into the wasm heap (MEMFS).

// @ts-expect-error - the ESM wasm artifact is generated by emcc.
import createXicap from "../dist/xicap.js";

export const enum PacketDirection {
    ServerToClient = 0,
    ClientToServer = 1,
}

export const enum Channel {
    Game = 0,
    Search = 1,
}

export const enum PacketFlag {
    ClientToServer = 0x0001,
    Injected = 0x0002,
    Blocked = 0x0004,
    Modified = 0x0008,
    FirstInChunk = 0x0010,
    Excluded = 0x0100,
    Redacted = 0x0200,
}

export const enum MarkerKind {
    Note = 0,
    Login = 1,
    Logout = 2,
}

export const enum ClockSource {
    Unknown = 0,
    Live = 1,
    Converted = 2,
}

export const enum Origin {
    Unknown = 0,
    Live = 1,
    Converted = 2,
}

export const enum Network {
    Unknown = 0,
    Retail = 1,
    Private = 2,
}

export const enum StartContext {
    Unknown = 0,
    Login = 1,
    MidSession = 2,
}

export const enum SeekResult {
    Ok = 0,
    EmptyIndex = 1,
    OutOfRange = 2,
    NotFound = 3,
}

// xicap::ErrorCode, in the order include/xicap/types.h declares it.
export const enum ErrorCode {
    OpenFailed = 0,
    BadMagic = 1,
    UnsupportedVersion = 2,
    DictionaryMismatch = 3,
    ShortHeader = 4,
    ShortExtension = 5,
    ExtensionTooLarge = 6,
    CorruptFrame = 7,
    FrameChecksumMismatch = 8,
    DecompressFailed = 9,
    ZstdContextFailed = 10,
    WriterClosed = 11,
    AddExtensionAfterPackets = 12,
    AddMarkerWithoutPacket = 13,
    PacketTooLarge = 14,
    CompressFailed = 15,
    HeaderChecksumMismatch = 16,
    ExtensionChecksumMismatch = 17,
    MissingPolicy = 18,
    UnknownFrameKind = 19,
    UnknownPacketFlag = 20,
    InvalidPolicy = 21,
    InvalidExtension = 22,
    WriteFailed = 23,
    PacketTooShort = 24,
    TranscodeRefused = 25,
    TranscodeMismatch = 26,
}

export class XicapError extends Error {
    readonly code: ErrorCode;
    constructor(message: string, code: ErrorCode) {
        super(message);
        this.name = "XicapError";
        this.code = code;
    }
}

function rethrowXicapError<T>(module: any, fn: () => T): T {
    try {
        return fn();
    } catch (e) {
        const last = module.__takeLastError();
        if (last) {
            throw new XicapError(last.message, last.code as ErrorCode);
        }
        throw e;
    }
}

export interface CharacterIdentity {
    contentId: number;
    characterId: number;
    worldId: number;
    characterName: string;
    worldName: string;
}

export interface ExclusionPolicy {
    name: string;
    version: number;
    rules: {
        channel: number;
        direction: number;
        action: number;
        opcode: number;
        ranges: { offset: number; length: number }[];
    }[];
}

export interface SourceInfo {
    format: string;
    formatVersion: string;
    skippedRecords: number;
    utcOffsetSeconds: number;
    sourceHash: Uint8Array;
    metadata: Uint8Array;
}

// The seal of a program that rewrote the file.
export interface Seal {
    key: Uint8Array;
    agent: string;
    sealedAtMs: number;
    // Its signature verifies over every packet of the file.
    good: boolean;
}

export interface Verification {
    key: Uint8Array;
    signedToEnd: boolean;
    verifiedPackets: number;
    goodCheckpoints: number;
    firstFailureOffset: number | null;
    seal: Seal | null;
}

export interface ZoneEntry {
    zoneId: number;
    timestampMs: number;
    fileOffset: number;
}

export interface Marker {
    kind: MarkerKind;
    text: string;
}

export interface Packet {
    timestampMs: number;
    channel: number;
    opcode: number;
    flags: number;
    direction: PacketDirection;
    data: Uint8Array;
    markers: Marker[];
}

export interface OpenOptions {
    // Skip damaged frames instead of refusing a complete file or ending a
    // cut-off one. For salvage only.
    recovery?: boolean;
}

let modulePromise: Promise<any> | null = null;
function getModule(): Promise<any> {
    modulePromise ??= createXicap();
    return modulePromise;
}

let nextHandle = 0;

export class Reader {
    static async open(bytes: ArrayBuffer | ArrayBufferView, options: OpenOptions = {}): Promise<Reader> {
        const module = await getModule();
        const u8 =
            bytes instanceof Uint8Array
                ? bytes
                : ArrayBuffer.isView(bytes)
                  ? new Uint8Array(bytes.buffer, bytes.byteOffset, bytes.byteLength)
                  : new Uint8Array(bytes);
        const path = `/xicap-${nextHandle++}-${Date.now()}.xicap`;
        module.FS.writeFile(path, u8);
        try {
            const native = rethrowXicapError(module, () => new module.Reader(path, options.recovery ?? false));
            return new Reader(native, module, path);
        } catch (e) {
            module.FS.unlink(path);
            throw e;
        }
    }

    private closed = false;

    private constructor(
        private readonly native: any,
        private readonly module: any,
        private readonly path: string,
    ) {}

    close(): void {
        if (this.closed) return;
        this.closed = true;
        this.native.delete();
        try {
            this.module.FS.unlink(this.path);
        } catch {}
    }

    get versionMajor(): number { return this.native.versionMajor(); }
    get versionMinor(): number { return this.native.versionMinor(); }
    get clientVersion(): string { return this.native.clientVersion(); }
    get captureAgent(): string { return this.native.captureAgent(); }
    get captureId(): Uint8Array { return this.native.captureId(); }
    get previousCaptureId(): Uint8Array { return this.native.previousCaptureId(); }
    get signingKey(): Uint8Array { return this.native.signingKey(); }
    get clockSource(): ClockSource { return this.native.clockSource(); }
    get origin(): Origin { return this.native.origin(); }
    get network(): Network { return this.native.network(); }
    get startContext(): StartContext { return this.native.startContext(); }
    get startTimestampMs(): number { return this.native.startTimestampMs(); }
    get endTimestampMs(): number { return this.native.endTimestampMs(); }
    get durationMs(): number { return this.native.durationMs(); }
    get totalFrames(): number { return this.native.totalFrames(); }
    get totalPacketCount(): number { return this.native.totalPacketCount(); }
    get complete(): boolean { return this.native.complete(); }
    get footerDamaged(): boolean { return this.native.footerDamaged(); }
    get unreadBytes(): number { return this.native.unreadBytes(); }
    // Known for the whole capture once every packet has been read.
    get characterMismatch(): boolean { return this.native.characterMismatch(); }
    get character(): CharacterIdentity { return this.native.character(); }
    get policy(): ExclusionPolicy { return this.native.policy(); }
    get source(): SourceInfo | null { return this.native.source(); }

    // Checks every signature over the whole file.
    verify(): Verification {
        return rethrowXicapError(this.module, () => this.native.verify());
    }

    skippedRegions(): { offset: number; length: number }[] {
        return this.native.skippedRegions();
    }

    extensionTypes(): number[] {
        return this.native.extensionTypes();
    }

    // A copy of the extension's bytes, or null.
    getExtension(type: number): Uint8Array | null {
        return this.native.getExtension(type) ?? null;
    }

    listZones(): ZoneEntry[] {
        return this.native.listZones();
    }

    // Yields packets in order. Each Packet.data is a copy the caller may keep.
    *[Symbol.iterator](): IterableIterator<Packet> {
        while (true) {
            const p = rethrowXicapError(this.module, () => this.native.next());
            if (!p) return;
            yield p as Packet;
        }
    }

    skipCurrentFrame(): void {
        this.native.skipCurrentFrame();
    }

    seekToFrame(frameIndex: number): SeekResult {
        return rethrowXicapError(this.module, () => this.native.seekToFrame(frameIndex));
    }

    seekToTime(timestampMs: number): SeekResult {
        return rethrowXicapError(this.module, () => this.native.seekToTime(timestampMs));
    }

    seekToZone(zoneId: number): SeekResult {
        return rethrowXicapError(this.module, () => this.native.seekToZone(zoneId));
    }
}

// Reads a capture as its bytes arrive, holding only the frame being received and one zstd stream's history. It stops
// at the first bytes that are not a whole, valid frame: in a complete file, the footer.
export class StreamReader {
    static async create(): Promise<StreamReader> {
        const module = await getModule();
        return new StreamReader(new module.StreamReader(), module);
    }

    private closed = false;

    private constructor(
        private readonly native: any,
        private readonly module: any,
    ) {}

    // The packets whose frames this chunk completed. Throws XicapError when the
    // file must be refused.
    push(chunk: Uint8Array): Packet[] {
        return rethrowXicapError(this.module, () => this.native.push(chunk));
    }

    // True once the header and extension blocks have arrived.
    get ready(): boolean { return this.native.ready(); }
    // True once the reader met bytes that are not a whole, valid frame.
    get stopped(): boolean { return this.native.stopped(); }
    get unreadBytes(): number { return this.native.unreadBytes(); }
    get versionMajor(): number { return this.native.versionMajor(); }
    get startTimestampMs(): number { return this.native.startTimestampMs(); }
    get origin(): Origin { return this.native.origin(); }
    get character(): CharacterIdentity { return this.native.character(); }
    get clientVersion(): string { return this.native.clientVersion(); }
    get captureAgent(): string { return this.native.captureAgent(); }

    close(): void {
        if (this.closed) return;
        this.closed = true;
        this.native.delete();
    }
}
